## Die Anbindung an After Effects

Jede Einblendung ist eine Komposition mit benannten Textebenen. Das Skript sucht sie über den Namen, setzt die Werte und legt die Komposition in die Renderliste.

```jsx
function baueEinblendung(daten) {
    var vorlage = findeComp("TPL_Geld");
    var comp    = vorlage.duplicate();
    comp.name   = daten.teilnehmer + "_" + daten.szene;

    setzeText(comp, "EUR_Summe", formatEuro(daten.eur));
    setzeText(comp, "Delta",     (daten.delta > 0 ? "+" : "") + kurz(daten.delta));

    var farbe = comp.layer("BG_Pille").property("Contents")
                    .property("Fill 1").property("Color");
    farbe.setValue(hexZuRgb(daten.teamfarbe));

    var eintrag = app.project.renderQueue.items.add(comp);
    eintrag.outputModule(1).file = new File(daten.ziel);
    return comp;
}
```

